import React, { useEffect } from "react";
import { Text, View, FlatList, TouchableOpacity, Image, StyleSheet, Dimensions } from "react-native";
import { useQuery } from "@apollo/client";
import { EDI_ORDER_QUERY } from "../../gql/Query";
import { useNavigation } from "@react-navigation/native";
import { Feather } from "@expo/vector-icons";

const spacing = 5;
const width = (Dimensions.get('window').width - 2) / 2;
const height = Dimensions.get('window').height;

export const EdiOrderDetailsScreenOpen = ({ paramData, onProductCountChange }) => {
  const { data, loading, error } = useQuery(EDI_ORDER_QUERY, {
    variables: { orderId: paramData.id },
  });

  const navigation = useNavigation();

  const openProducts = data?.order?.orderProducts?.filter(prod => prod.isOpen) || [];
  
  useEffect(() => {
    onProductCountChange(openProducts.length);
  }, [openProducts.length]);

  if (loading) return <Text>Loading...</Text>;
  if (error || !data?.order) return <Text>Error loading data or no order found.</Text>;

  const OpenOrderQueryItem = ({ item }) => {
    const { code, name, quantityPerBox } = item.product;
    const { initialQuantity, finalQuantity } = item;
    const supplierName = data.order.supplier.name;
    const orderId = data.order.id;
    const productId = item.product.id;

    return (
      <TouchableOpacity 
        onPress={() => navigation.navigate("EdiItemApprovalScreen", {
          paramData: item.product,
          initialQuantity,
          finalQuantity,
          supplier: supplierName,
          orderId,
          productId
        })}
      >
        <View style={styles.item}>
          <View style={styles.top}>
            <View style={styles.left}>
              <Text style={styles.boxes}>{quantityPerBox}</Text>
              <Feather name="box" size={26} color="black" />
            </View>
            <Image style={styles.img} source={require('../../assets/gamadim.png')} />
          </View>
          <View style={styles.bottom}>
            <Text style={styles.quantity}>Quantity: {initialQuantity}</Text>
            <Text style={styles.reference}>{name}</Text>
            <Text style={styles.barcode}>{code}</Text>
          </View>
        </View>
      </TouchableOpacity>
    );
  };

  return (
    <View style={styles.container}>
      <FlatList
        style={styles.flat}
        data={openProducts}
        renderItem={({ item }) => <OpenOrderQueryItem item={item} />}
        keyExtractor={(item) => item.id}
        numColumns={2}
        columnWrapperStyle={styles.column}
      />
      <TouchableOpacity style={styles.closeButton} onPress={() => navigation.navigate("EdiCertificateApprovalScreen", { paramData })}>
        <Text style={styles.closeButtonText}>Close Certificate from Open</Text>
      </TouchableOpacity>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    backgroundColor: "#7CA1B4",
    alignItems: 'center',
    height: height - 300,
  },
  flat: {
    display: 'flex',
  },
  item: {
    backgroundColor: 'white',
    padding: 18,
    margin: 5,
    borderRadius: 20,
    width: width - 8,
  },
  closeButton: {
    backgroundColor: 'blue',
    borderRadius: 10,
    flexDirection: 'row',
    justifyContent: 'space-evenly',
    alignItems: 'center',
    width: '95%',
    padding: 18,
  },
  closeButtonText: {
    color: 'white',
    fontSize: 22,
  },
  top: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: 5,
    marginBottom: 15,
  },
  left: {
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  boxes: {
    fontSize: 18,
    padding: 5,
  },
  img: {
    width: 100,
    height: 100,
  },
  bottom: {
    textAlign: 'right',
  },
  quantity: {
    fontSize: 20,
  },
  reference: {
    fontSize: 24,
    color: 'blue',
  },
  barcode: {
    fontSize: 18,
  },
  column: {
    flexShrink: 1,
  },
});
